/// <summary>
/// Parent class to post the shipment
/// </summary>
abstract class METOrderShipmentConfirmation
{
    METSalesOrderShipmentLoadHeader        metSalesOrderShipmentLoadHeader;
    DocumentStatus      documentStatus;

}

Method.Source:
/// <summary>
/// Construct method for the class
/// </summary>
/// <param name = "_shipmentId">ShipmentId</param>
/// <returns>METOrderShipmentConfirmation</returns>
public static METOrderShipmentConfirmation construct(MetShipmentId _shipmentId)
{
    METSalesOrderShipmentLoadHeader metSalesOrderShipmentLoadHeader;
    METOrderShipmentConfirmation    metOrderShipmentConfirmation;

    select firstonly metSalesOrderShipmentLoadHeader
            where metSalesOrderShipmentLoadHeader.ShipmentId == _shipmentId;

    if (metSalesOrderShipmentLoadHeader.TransactionType == METOrderTransactionType::SalesOrder)
    {
        metOrderShipmentConfirmation = new METOrderShipmentConfirmation_SalesOrder(metSalesOrderShipmentLoadHeader);
    }
    else if (metSalesOrderShipmentLoadHeader.TransactionType == METOrderTransactionType::TransferOrder)
    {
        metOrderShipmentConfirmation = new METOrderShipmentConfirmation_TransferOrder(metSalesOrderShipmentLoadHeader);
    }

    if (!_shipmentId)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    return metOrderShipmentConfirmation;
}

/// <summary>
/// New method for class
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadHeader">ShipmentId reference</param>
protected void new(METSalesOrderShipmentLoadHeader _metSalesOrderShipmentLoadHeader)
{
    metSalesOrderShipmentLoadHeader = _metSalesOrderShipmentLoadHeader;
}

/// <summary>
/// Abstract method to have business logic for post method
/// </summary>
/// <returns>boolean value</returns>
abstract boolean post()
{
}

/// <summary>
/// Run method to initiate business logic
/// </summary>
public void run()
{
    boolean  result = false;

    ttsbegin;

    result = this.post();

    if (result)
    {
        METSalesOrderShipmentLoadHeader::updateDocStatusInHeader(MetShipmentStatus::Shipped, documentStatus, metSalesOrderShipmentLoadHeader.ShipmentId);

        metSalesOrderShipmentLoadHeader.reread();

        if (metSalesOrderShipmentLoadHeader.LoadStatus == MetLoadStatus::Shipped)
        {
            METSalesOrderShipmentLoadHeader::processsPickupAdvice(metSalesOrderShipmentLoadHeader.LoadId);
        }
    }
    else
    {
        METSalesOrderShipmentLoadHeader::updateDocStatusInHeader(MetShipmentStatus::Open, documentStatus, metSalesOrderShipmentLoadHeader.ShipmentId);
    }

    ttscommit;

    if (metSalesOrderShipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Shipped)
    {
        METTMSEngineExecutionMode tmpEngineExecutionMode;

        if (metSalesOrderShipmentLoadHeader.TransactionType == METOrderTransactionType::SalesOrder)
        {
            tmpEngineExecutionMode = METTMSEngineExecutionMode::SalesOrderPackingSlip;
        }
        else
        {
            tmpEngineExecutionMode = METTMSEngineExecutionMode::TransferOrderShipped;
        }

        // CB626_TMSEngineSOPackingSlip Triggers for the TMS Engine processing on SO Delivery Note Posting
        // outside the ttscommit so in case of error does not rollback the packing slip posting
        METTMSEngineOrderProccess::construct(METTMSEngineExecutionMode::TransferOrderShipped, metSalesOrderShipmentLoadHeader).run();
    }
}
